int main(void) {
    char c;
    int vitorias = 0;

    for (int i = 0; i < 6; i++) {
        if (scanf(" %c", &c) == 1) {
            if (c == 'V') {
                vitorias++;
            }
        }
    }

    if (vitorias >= 5) {
        printf("1\n");
